  str_cn9_item_intro_7000700 = "Una bandeja de porcelana cubierta con un esmalte blanco puro. Delicados patrones que parecen fragmentos de hielo rotos adornan su superficie.",
  str_cn9_item_intro_7000701 = "Una taza de porcelana cubierta con un esmalte blanco. Su borde ovalado se extiende delicadamente hacia afuera, y la base adopta la forma de ramas de árbol. El cuerpo de la taza muestra intrincadas flores de ciruelo tridimensionales de notable delicadeza.",
  str_cn9_item_intro_7000702 = [[
